def coil_stock_table(root):
 return batch6_stock_table(root,'helical_insert_sizes',['thread','length_multiple','configuration'],['Mating thread reference','Nominal installed length','Construction / finish'],root+' stocked helical-insert references')+'<p>D identifies nominal mating-thread diameter. 1D, 1.5D and 2D describe nominal installed insert length as a multiple of D. They do not specify free-coil length, tapped-hole diameter or installation depth.</p>'
guide('Reference-MS16555-MS16556.html','MS16555 Stocked Dowel Pins | MS16556 Fit Comparison','MS16555 and MS16556 dowel pins.','Find selected stocked MS16555 dowel pins, compare nominal sizes and preserve the different MS16556 fit requirement.',[
 ('Stocked MS16555 part numbers',pin_stock_table('MS16555'),'STOCKED SELECTION'),
 ('A small diameter distinction matters','<p>The series descriptions distinguish MS16555 as .0002 over nominal size and MS16556 as .001 over nominal size. Those family descriptions identify different fit requirements. They do not mean the pin can be selected using nominal diameter alone.</p>'+kv([('MS16555','Dowel pin family; .0002 over nominal'),('MS16556','Dowel pin family; .001 over nominal')],'Dowel pin family distinction')+source_note(['D-MS16555','D-MS16556']),'FIT REFERENCE'),
 ('Document succession','<p>The official records identify NASM16555 and NASM16556 as the respective successor documents. Check the complete part designation and applicable issue for the selected material, diameter limits, end configuration and length.</p>','STANDARD REFERENCES'),
 ('Solid dowel versus spring pin','<p>A solid dowel and a tubular spring pin behave differently in a mating hole. Do not exchange one for the other based on nominal size. Include the required interference or clearance and retain the pin type on the drawing.</p>'+chips([('Slotted spring-pin reference','Reference-MS16562.html')]),'RELATED HARDWARE')])

guide('Reference-MS16562.html','MS16562 Slotted Spring Pins | Stocked Sizes','MS16562 slotted spring pins.','Compare selected stocked MS16562 slotted spring-pin sizes and distinguish them from solid dowels and coiled spring pins.',[
 ('Stocked MS16562 part numbers',pin_stock_table('MS16562'),'STOCKED SELECTION'),
 ('Identify the pin construction','<p>MS16562 refers to slotted tubular spring pins. The slot and spring section distinguish the family from solid dowels. A drawing can also control the mating hole, installed fit, material and treatment.</p>'+kv([('MS16562','Slotted tubular spring pins'),('MS51923','Medium-duty coiled spring pins'),('MS39086','Heavy-duty coiled spring pins'),('MS16555 / MS16556','Solid dowel families')],'Pin construction comparison')+source_note(['NASM16562','G']),'PIN TYPES'),
 ('Applicable reference','<p>NASM16562 is an active standard for slotted tubular spring pins. Include the exact drawing callout and issue when asking Webson to review a legacy MS16562 requirement.</p>'+source_note(['NASM16562']),'STANDARD REFERENCE'),
 ('What to measure','<p>Record nominal pin diameter, free-state diameter limits where specified, length and the mating-hole requirement. The free pin diameter is not necessarily the same as the hole diameter. Use the specified standard for the relationship.</p>','ORDERING DETAILS')])

guide('Reference-MS20426-MS20470.html','MS20426 and MS20470 Solid Rivets | Stocked Sizes','MS20426 and MS20470 solid rivets.','Look up selected stocked MS20426 countersunk and MS20470 universal-head solid rivets, compare sizes and request pricing from Webson.',[
 ('Stocked MS20426 part numbers',solid_stock_table('MS20426'),'STOCKED SELECTION'),
 ('Stocked MS20470 part numbers',solid_stock_table('MS20470'),'STOCKED SELECTION'),
 ('Keep the length convention with the head style','<p>MS20426 countersunk-rivet length includes the head. MS20470 universal-head length is measured beneath the head. Neither measure is the grip-range convention used for a blind rivet.</p><p>For the selected aluminum entries, material code A identifies 1100 and AD identifies 2117. A terminal A identifies clear anodize; it serves a different role from an A material code. Unsuffixed selected entries use chemical surface treatment.</p><p>MS20426AD3-5.5 has a nominal 3/32-inch shank diameter and 11/32-inch overall length, including the countersunk head.</p>','LENGTH AND FINISH'),
 ('Start with the installed head','<p>MS20426 identifies a 100-degree countersunk precision-head solid-rivet family. MS20470 is a universal-head solid-rivet family. The head shape and required seat differ, so diameter and length alone do not establish an alternate.</p>'+kv([('MS20426','100-degree countersunk precision head'),('MS20470','Universal head')],'Solid-rivet head comparison')+source_note(['D-MS20426','G']),'HEAD GEOMETRY'),
 ('An example of unchanged part numbers','<p>MS20426 has the successor document NASM20426, with the original part identification numbers retained. A NASM document title therefore does not mean an MS part number must be renamed by changing its prefix.</p>'+source_note(['MS20426-NOTICE']),'DOCUMENT AND PART NUMBER'),
 ('Order the entire rivet requirement','<p>Record material/finish codes, diameter and length or grip requirements. Confirm whether a specified length is measured under the head or includes it; use the governing drawing. Installation access and process requirements remain separate from this family comparison.</p>'+chips([('Rivet series directory',familyfile('Rivets'))]),'PURCHASING DETAILS')])

guide('Reference-MS21209.html','MS21209 Helical Inserts | Stocked Screw-Locking Configurations','MS21209 screw-locking helical-coil inserts.','Identify selected stocked MS21209 tanged screw-locking inserts, compare mating threads and installed-length multiples, and request a quote from Webson.',[
 ('A tanged insert with a screw-locking feature','<p>MS21209 identifies corrosion-resistant helical-coil screw-thread inserts with a locking feature. The installation tang and locking construction distinguish this selection from a free-running tangless insert.</p>','PART IDENTIFICATION'),
 ('Stocked MS21209 part numbers',coil_stock_table('MS21209'),'STOCKED SELECTION'),
 ('Keep size and finish codes intact','<p>MS21209C0415 references a 4-40 coarse thread and 1.5D installed length. MS21209F1-15 references a 10-32 fine thread and 1.5D installed length.</p><p>For the selected entries, terminal L identifies dry-film lubricant and P identifies cadmium plating. These are finish identifiers, not changes in the installed-length multiple.</p><p>MS21209-C5-10 is a stainless-steel screw-locking insert for a 5/16-18 UNC thread, with a nominal installed length of 1D (0.312 inch).</p>','PART-NUMBER REVIEW'),
 ('Specify the insert and installation requirements together','<p>Provide the mating thread, installed length, required locking style and finish. Include the controlling hole-preparation and installation requirements, parent material and any approved-source restrictions.</p><p>A mating-thread match does not approve exchanging tanged, tangless, free-running and screw-locking inserts.</p>','RFQ DETAILS'),
 ('Related insert families',chips([('NAS1130 tangless helical inserts','Reference-NAS1130.html'),('MS51830 keylocking insert reference','Reference-MS51830.html'),('All insert families',familyfile('Threaded inserts'))])+'<p>Send the complete designation, quantity, required date and documentation requirements to Webson.</p>','SOURCE WITH WEBSON')])

guide('Reference-NAS1130.html','NAS1130 Tangless Inserts | Stocked Free-Running and Locking Parts','NAS1130 tangless helical-coil inserts.','Compare selected stocked NAS1130 free-running and screw-locking tangless inserts, thread references, installed-length multiples and finish details.',[
 ('Tangless construction with distinct locking options','<p>NAS1130 identifies tangless helical-coil screw-thread inserts in free-running and screw-locking versions. Preserve the specified construction when requesting a quote.</p>','PART IDENTIFICATION'),
 ('Stocked NAS1130 part numbers',coil_stock_table('NAS1130'),'STOCKED SELECTION'),
 ('Separate the locking and finish identifiers','<p>In the selected references, L before the length code identifies the screw-locking version. NAS1130-06-15 is free-running; NAS1130-06L15 is screw-locking. Both use 6-32 threads and 1.5D nominal installed length.</p><p>Terminal P identifies cadmium plating and D identifies dry-film lubricant. Keep their position and meaning separate from the L locking identifier.</p>','PART-NUMBER EXAMPLES'),
 ('Confirm the supply format','<p>The stocked NAS1130-06-10DSF entry retains a supplier ordering identifier for a dry-film-lubricated, strip-fed selection. SF is a supply-format identifier, not a separate size code in the standard NAS designation. Confirm the required manufacturer and bulk or strip-feed format with your inquiry.</p>','SUPPLY FORMAT'),
 ('Review the complete requirement',chips([('MS21209 tanged screw-locking inserts','Reference-MS21209.html'),('Keylocking insert reference','Reference-MS51830.html'),('All insert families',familyfile('Threaded inserts'))])+'<p>Provide the complete callout, quantity, required date, installation requirements and any certificates or traceability needed for the order.</p>','SOURCE WITH WEBSON')])

guide('Reference-MS16535.html','MS16535 Tubular Rivets | Stocked Oval-Head Sizes','MS16535 oval-head tubular rivets.','Find selected stocked MS16535 tubular rivets in aluminum, nickel-plated brass and carbon steel, with body-diameter limits and nominal lengths.',[
 ('Oval head with a tubular end','<p>MS16535 identifies oval-head tubular rivets. The tubular end is formed during installation, so body diameter, under-head length and the required upset all belong in the requirement.</p>','PART IDENTIFICATION'),
 ('Stocked MS16535 part numbers',stocked_reference_table('MS16535','tubular_rivet_sizes',['body_diameter_limits','length','configuration'],['Body diameter limits (in)','Nominal under-head length (in)','Material / configuration'],'MS16535 stocked tubular-rivet references'),'STOCKED SELECTION'),
 ('Read body diameter separately from the hole size','<p>The selected MS16535-77 and MS16535-66N rivets have body-diameter limits of 0.085–0.089 inch. MS16535-3 uses a smaller 0.058–0.061-inch body.</p><p>The mounting-hole requirement and tubular-end dimensions are separate drawing features. The table length is measured beneath the oval head.</p>','DIMENSION REFERENCE'),
 ('Preserve the material and finish designation','<p>MS16535-77 is aluminum, MS16535-66N is nickel-plated brass and MS16535-3 is cadmium-plated carbon steel. The N finish identifier on the brass entry must remain in the part number.</p>','MATERIAL AND FINISH'),
 ('Specify the complete rivet requirement','<p>Include the full designation, quantity, material-stack thickness, installation requirements and required documentation with your inquiry. MS20426 and MS20470 are separate solid-rivet families with different head configurations.</p>'+chips([('MS20426 and MS20470 solid rivets','Reference-MS20426-MS20470.html'),('Rivet family directory',familyfile('Rivets'))]),'SOURCE WITH WEBSON')])

guide('Reference-MS16633.html','MS16633 Retaining Rings | Stocked External E-Rings','MS16633 external E retaining rings.','Look up selected stocked MS16633 external E-rings by shaft-diameter reference, basic ring thickness and material/finish.',[
 ('External E-type retaining rings','<p>MS16633 identifies reduced-section external E retaining rings. The ring seats in a shaft groove to retain a component axially.</p><p>The shaft diameter, groove geometry and retained-part geometry work together in selecting the required ring.</p>','PART IDENTIFICATION'),
 ('Stocked MS16633 part numbers',stocked_reference_table('MS16633','retaining_ring_sizes',['shaft_diameter','basic_thickness','configuration'],['Shaft diameter reference (in)','Basic ring thickness T (in)','Material / finish'],'MS16633 stocked external E-ring references')+'<p>T is the basic thickness dimension. Finished thickness limits include the material and finish allowances specified in the drawing.</p>','STOCKED SELECTION'),
 ('A shaft reference is different from a free ring diameter','<p>MS16633-4006 references a 0.062-inch shaft, while MS16633-4009 references a 0.094-inch shaft. The free ring opening and groove diameter have separate dimensions.</p><p>Use the specified groove diameter, width and corner geometry when reviewing the application.</p>','SIZE SELECTION'),
 ('The dash number carries the material group','<p>MS16633-1014 is a cadmium-plated carbon spring steel selection. The selected -4006, -4009 and -4018 entries are passivated corrosion-resistant steel.</p><p>Retain the full dash number when ordering so the required size, material and finish remain together.</p>','MATERIAL IDENTIFICATION'),
 ('Send the application requirement','<p>Provide the complete part number, quantity, required date, governing issue and certification requirements. Include any application drawing or approved-source requirements that affect the order.</p>'+chips([('Retaining-ring family directory',familyfile('Retaining rings')),('RFQ preparation checklist','Resources-Mil-Spec-RFQ-Checklist.html')]),'SOURCE WITH WEBSON')])


def final_stock_table(root,key,fields,headers,caption):
 file=guide_map[root]
 rows=[]
 for r in D[key][root]:
  link='Quote.html?reference='+file+'&amp;part='+h(r['part'])
  rows.append({'cells':[h(r['part'])]+[h(r[k]) for k in fields]+['Stocked item','<a href="'+link+'">Quote '+h(r['part'])+' →</a>'],'search':' '.join(r.values())})
 return '<p>Selected stocked part numbers and identification references. Dimensions are in inches; nominal values and limits are identified in the column headings.</p>'+filtered(['Part number']+headers+['Stock status','Request pricing'],rows,caption)+STOCK_NOTE

guide('Reference-NAS662.html','NAS662 Screws | Stocked Miniature 100-Degree Flat Heads','NAS662 miniature flat-head screws.','Compare selected stocked NAS662 stainless screws, nominal overall lengths, threads and patch-locking configurations.',[
 ('100-degree head with cross-recessed drive','<p>The selected NAS662 entries have a 100-degree flat head and a cross-recessed drive. The stocked selection includes 2-56 coarse threads and a 0-80 fine-thread patch-locking configuration.</p>','PART IDENTIFICATION'),
 ('Stocked NAS662 part numbers',final_stock_table('NAS662','machine_screw_sizes',['thread','length','configuration'],['Thread reference','Nominal overall length (in)','Material / locking configuration'],'NAS662 stocked miniature screw references'),'STOCKED SELECTION'),
 ('Overall length includes the countersunk head','<p>For these flat-head screws, nominal length includes the head. NAS662C2R2 is a 2-56 by 1/8-inch selection; NAS662C2R9 is a 2-56 by 9/16-inch selection.</p>','LENGTH CONVENTION'),
 ('Keep the locking identifier in the callout','<p>NAS662C2LPR3 and NAS662C2R3 share a 2-56 thread and 3/16-inch nominal length. The LPR designation retains the patch-type locking configuration and cross-recessed drive.</p><p>NAS662C0LPR3 uses a 0-80 thread. Preserve the complete size and locking designation when ordering.</p>','LOCKING CONFIGURATION'),
 ('Compare the head and thread together','<p>MS24693 also uses a 100-degree flat head, while MS51959 uses an 82-degree head. Retain the complete material, thread, length and locking requirement in any comparison.</p>'+chips([('MS24693 flat-head screws','Reference-MS24693.html'),('MS51959 82-degree screws','Reference-MS51959.html'),('Machine-screw directory',familyfile('Machine screws'))]),'RELATED REFERENCES')])

guide('Reference-NAS8100-NAS8101.html','NAS8100 and NAS8101 Screws | Stocked A286 Pan Heads','NAS8100 and NAS8101 A286 pan-head screws.','Find selected stocked A286 pan-head screws with ribbed cruciform recesses, compare 4-40 and 6-32 threads, and request a quote.',[
 ('A286 material and ribbed cruciform recess','<p>NAS8100 and NAS8101 identify pan-head screws within an A286 corrosion-resistant steel family. The selected NAS8100 entries use 4-40 UNJC-3A threads; NAS8101U8 uses 6-32 UNJC-3A.</p>','PART IDENTIFICATION'),
 ('Stocked NAS8100 part numbers',final_stock_table('NAS8100','machine_screw_sizes',['thread','length','configuration'],['Thread reference','Nominal under-head length (in)','Material / finish'],'NAS8100 stocked A286 pan-head screw references'),'STOCKED SELECTION'),
 ('Stocked NAS8101 part number',final_stock_table('NAS8101','machine_screw_sizes',['thread','length','configuration'],['Thread reference','Nominal under-head length (in)','Material / finish'],'NAS8101 stocked A286 pan-head screw reference'),'STOCKED SELECTION'),
 ('Finish and locking codes serve different purposes','<p>U identifies the cleaned and passivated finish in these selected entries. The hyphen in NAS8100-6 identifies the cadmium-plated configuration. The listed selections are nonlocking.</p><p>NAS8100U6 and NAS8100-6 share a 4-40 thread and 3/8-inch nominal under-head length, with different finishes.</p>','FINISH IDENTIFICATION'),
 ('Measure beneath the pan head','<p>Nominal screw length runs from the bearing surface beneath the head to the tip. Include the exact thread, finish, recess, quantity and documentation requirements with your inquiry.</p>'+chips([('MS51957 stainless pan-head screws','Reference-MS51957.html'),('Machine-screw directory',familyfile('Machine screws'))]),'SOURCE WITH WEBSON')])

guide('Reference-MS21044.html','MS21044 Locknuts | Stocked Regular-Height Insert Nuts','MS21044 regular-height insert locknuts.','Compare selected stocked MS21044 steel and CRES nonmetallic-insert locknuts by thread and material/finish.',[
 ('Regular-height nonmetallic-insert construction','<p>MS21044 identifies regular-height hexagon self-locking nuts with a nonmetallic insert. The locking construction and height envelope belong with the thread and material in the ordering requirement.</p>','PART IDENTIFICATION'),
 ('Stocked MS21044 part numbers',final_stock_table('MS21044','nut_sizes',['thread','material'],['Thread reference','Material / locking configuration'],'MS21044 stocked insert-locknut references'),'STOCKED SELECTION'),
 ('Read the material and size codes separately','<p>MS21044C06 references a passivated CRES selection with a 6-32 thread. MS21044N04 references a cadmium-plated steel selection with a 4-40 thread.</p><p>The N3 and N4 entries identify 10-32 and 1/4-28 threads respectively. Preserve the significant leading zeroes in the smaller size codes.</p>','PART-NUMBER EXAMPLES'),
 ('Compare locking construction and height','<p>MS21042 is a reduced-height all-metal locking family. MS21083 is a low-height nonmetallic-insert family. Their envelopes and locking mechanisms have separate requirements.</p>'+chips([('MS21042 all-metal locknuts','Reference-MS21042.html'),('MS21083 low-height insert locknuts','Reference-MS21083.html'),('Nut family directory',familyfile('Nuts'))]),'FAMILY COMPARISON')])

guide('Reference-MS21042.html','MS21042 Locknuts | Stocked Reduced-Height All-Metal Nuts','MS21042 reduced-height locking nuts.','Find selected stocked MS21042 all-metal locknuts, compare thread and lubrication references, and review related locking-nut families.',[
 ('Stocked MS21042 part numbers',final_stock_table('MS21042','nut_sizes',['thread','material'],['Thread reference','Material / locking configuration'],'MS21042 stocked all-metal locknut references'),'STOCKED SELECTION'),
 ('A distinct locking-nut envelope','<p>The series identifies MS21042 as a reduced-hexagon, reduced-height, ring-base self-locking nut family in non-corrosion-resistant steel, with a 450-degree-F designation. Check the governing issue for detailed material, finish and performance requirements.</p>'+source_note(['D-MS21042']),'IDENTIFICATION'),
 ('Document reference','<p>The document status review identifies MS21042 as canceled and superseded by NASM21042. Use the original drawing callout and required revision when requesting a quote; do not infer a full replacement designation from the document name alone.</p>','STANDARD STATUS'),
 ('Compare locking-nut families','<p>Reduced-height, regular-height and nonmetallic-insert nuts differ in envelope and locking construction. They should not be grouped as equivalent simply because they accept the same screw thread.</p>'+kv([('MS21042','Reduced-height, reduced-hex locking family'),('MS21044','Regular-height locking family'),('MS21083','Low-height nonmetallic-insert family')],'Locknut family identification')+source_note(['G'])+chips([('MS21044 regular-height insert locknuts','Reference-MS21044.html'),('Nut reference directory',familyfile('Nuts'))]),'RELATED SERIES')])

guide('Reference-MS21075-MS21077.html','MS21075 and MS21077 Nutplates | Stocked Floating Configurations','MS21075 and MS21077 floating nutplates.','Identify selected stocked floating nutplates, compare thread and locking construction, and preserve lubrication and eyelet codes.',[
 ('Two floating nutplate families','<p>MS21075 identifies low-height, reduced-rivet-spacing steel floating nutplates. MS21077 identifies two-lug floating nutplates with nonmetallic-insert locking construction.</p><p>Mounting geometry, nut height and locking construction remain part of the complete requirement.</p>','PART IDENTIFICATION'),
 ('Stocked MS21075 part numbers',final_stock_table('MS21075','stocked_nutplate_references',['thread','configuration'],['Thread reference','Construction / lubrication'],'MS21075 stocked floating nutplate references'),'STOCKED SELECTION'),
 ('Stocked MS21077 part number',final_stock_table('MS21077','stocked_nutplate_references',['thread','configuration'],['Thread reference','Construction'],'MS21077 stocked floating nutplate reference'),'STOCKED SELECTION'),
 ('Retain L and N in the MS21075 designation','<p>L identifies dry-film lubricant in the selected MS21075 entries. N identifies the configuration without eyelets. MS21075L3N and MS21075-3N share a 10-32 thread while retaining different lubrication callouts.</p><p>The selected non-dry-film entries are cadmium-plated steel. Keep the required coating with the complete specification callout for dry-film-lubricated versions.</p>','CODE IDENTIFICATION'),
 ('Review the complete mounting requirement','<p>MS21077-08 uses an 8-32 thread and nonmetallic-insert locking construction. Include rivet spacing, hole style, nut height, quantity and documentation requirements with the part number.</p>'+chips([('MS21076 CRES floating nutplates','Reference-MS21076.html'),('NAS1791 replaceable-element nutplates','Reference-NAS1791.html'),('Nut family directory',familyfile('Nuts'))]),'SOURCE WITH WEBSON')])

guide('Reference-MS27183.html','MS27183 Flat Washers | Stocked Steel Sizes and Dimension Limits','MS27183 flat steel washers.','Compare selected stocked MS27183 flat steel washers by fastener size and inside-diameter, outside-diameter and thickness limits.',[
 ('Match the washer envelope to the requirement','<p>MS27183 identifies general-purpose round flat metal washers. The selected stocked entries are carbon steel and reference #4 and #8 fastener sizes.</p>','PART IDENTIFICATION'),
 ('Stocked MS27183 part numbers',final_stock_table('MS27183','stocked_washer_sizes',['size','inside_diameter','outside_diameter','thickness','configuration'],['Fastener size (ref)','ID limits (in)','OD limits (in)','Thickness limits (in)','Material / style'],'MS27183 stocked flat-washer limits'),'STOCKED SELECTION'),
 ('Fastener size and washer dimensions are separate references','<p>MS27183-3 references a #4 fastener and has a 0.125–0.135-inch inside diameter. MS27183-5 references #8 and has a 0.187–0.197-inch inside diameter.</p><p>The table lists dimensional limits rather than nominal midpoints. Outside diameter and thickness also belong in the selection.</p>','SIZE IDENTIFICATION'),
 ('Preserve finish and documentation requirements','<p>Include the required protective finish, specification issue, quantity and certificates in your inquiry. Other flat-washer families use their own size and material codes.</p>'+chips([('MS15795 stainless flat washers','Reference-MS15795.html'),('AN960 and NAS1149 washers','Reference-AN960-NAS1149.html'),('Washer family directory',familyfile('Washers'))]),'SOURCE WITH WEBSON')])

guide('Reference-MS35333-MS35335.html','MS35333 and MS35335 Lock Washers | Stocked Internal and External Tooth','MS35333 and MS35335 tooth-lock washers.','Compare selected stocked internal- and external-tooth washers, fastener sizes, dimensional references and material groups.',[
 ('Internal and external tooth configurations','<p>MS35333 identifies internal-tooth lock washers. MS35335 identifies external-tooth lock washers. Retain the specified tooth location and contact geometry when sourcing the washer.</p>','PART IDENTIFICATION'),
 ('Stocked MS35333 internal-tooth washers',final_stock_table('MS35333','stocked_washer_sizes',['size','inside_diameter','outside_diameter','thickness','configuration'],['Fastener size (ref)','Nominal ID (in)','Nominal OD (in)','Nominal thickness (in)','Material / style'],'MS35333 stocked internal-tooth nominal references'),'STOCKED SELECTION'),
 ('Stocked MS35335 external-tooth washers',final_stock_table('MS35335','stocked_washer_sizes',['size','inside_diameter','outside_diameter','thickness','configuration'],['Fastener size (ref)','ID limits (in)','OD limits (in)','Thickness limits (in)','Material / style'],'MS35335 stocked external-tooth limits'),'STOCKED SELECTION'),
 ('Read the family and dash number together','<p>MS35333-36 and MS35335-57 both reference #4 fasteners, with different tooth configurations and material groups. The selected MS35333 entries are carbon steel; the selected MS35335 entries are passivated corrosion-resistant steel.</p><p>The internal-tooth table gives nominal identification dimensions. The external-tooth table gives dimension limits. Drawing requirements govern acceptance.</p>','SIZE AND MATERIAL'),
 ('Match the specified washer function','<p>Provide the complete washer designation, finish requirement, quantity and documentation requirements. Flat washers and helical spring lock washers have separate dimensional and construction references.</p>'+chips([('MS35338 helical spring washers','Reference-MS35338.html'),('MS27183 flat steel washers','Reference-MS27183.html'),('Washer family directory',familyfile('Washers'))]),'RELATED REFERENCES')])


